INSERT INTO kb_card_product_tbl (card_name, card_type, card_image, annual_fee)
SELECT #{cardName}, #{cardType}, #{cardImage}, #{annualFee}
FROM DUAL
WHERE NOT EXISTS (
    SELECT 1 FROM kb_card_product_tbl WHERE card_name = #{cardName}
)

