UPDATE card_transaction_detail_tbl
SET status = #{status},
    transaction_id = #{transactionId}
WHERE card_transaction_id = #{cardTransactionId}

UPDATE account_dummy_tbl
SET balance = balance - #{amount}
WHERE account_id = #{accountId}
  AND balance >= #{amount}

UPDATE account_dummy_tbl
SET balance = balance + #{amount}
WHERE account_id = #{accountId}

UPDATE wallet_tbl
SET balance = balance - #{amount}
WHERE user_id = #{userId}
  AND balance >= #{amount}
